CREATE TABLE {{schema}}.working_versions(tenant_id text NOT NULL,branch text NOT NULL,version bigint NOT NULL CHECK(version>0),content_hash text NOT NULL,payload text NOT NULL,PRIMARY KEY(tenant_id,branch,version));
CREATE TABLE {{schema}}.working_heads(tenant_id text NOT NULL,branch text NOT NULL,version bigint NOT NULL,PRIMARY KEY(tenant_id,branch),FOREIGN KEY(tenant_id,branch,version) REFERENCES {{schema}}.working_versions);
CREATE TABLE {{schema}}.summary_versions(tenant_id text NOT NULL,branch text NOT NULL,version bigint NOT NULL CHECK(version>0),id text NOT NULL,content_hash text NOT NULL,through_turn bigint NOT NULL CHECK(through_turn>=0),payload text NOT NULL,PRIMARY KEY(tenant_id,branch,version),UNIQUE(tenant_id,id));
CREATE TABLE {{schema}}.summary_heads(tenant_id text NOT NULL,branch text NOT NULL,version bigint NOT NULL,PRIMARY KEY(tenant_id,branch),FOREIGN KEY(tenant_id,branch,version) REFERENCES {{schema}}.summary_versions);
CREATE TABLE {{schema}}.history_source_pins(tenant_id text NOT NULL,source_id text NOT NULL,source_version text NOT NULL,branch text NOT NULL,turn bigint NOT NULL,content_hash text NOT NULL,PRIMARY KEY(tenant_id,source_id,source_version));
CREATE TABLE {{schema}}.source_tombstones(tenant_id text NOT NULL,source_id text NOT NULL,source_version text NOT NULL,reason text NOT NULL CHECK(reason IN ('source_revoked','source_deleted','source_corrected','consent_revoked')),PRIMARY KEY(tenant_id,source_id,source_version,reason));
CREATE TABLE {{schema}}.derived_refs(tenant_id text NOT NULL,id text NOT NULL,kind text NOT NULL CHECK(kind IN ('summary','candidate','history_index','context_cache')),source_hash text NOT NULL,invalid_reason text,PRIMARY KEY(tenant_id,id));
CREATE TABLE {{schema}}.source_edges(tenant_id text NOT NULL,derived_id text NOT NULL,source_id text NOT NULL,source_version text NOT NULL,PRIMARY KEY(tenant_id,derived_id,source_id,source_version),FOREIGN KEY(tenant_id,derived_id) REFERENCES {{schema}}.derived_refs,FOREIGN KEY(tenant_id,source_id,source_version) REFERENCES {{schema}}.history_source_pins);
CREATE TABLE {{schema}}.derived_runs(tenant_id text NOT NULL,derived_id text NOT NULL,run_id text NOT NULL,PRIMARY KEY(tenant_id,derived_id,run_id),FOREIGN KEY(tenant_id,derived_id) REFERENCES {{schema}}.derived_refs);
CREATE TABLE {{schema}}.historical_source_markers(tenant_id text NOT NULL,run_id text NOT NULL,source_id text NOT NULL,reason text NOT NULL,PRIMARY KEY(tenant_id,run_id,source_id,reason));
